window.AB_INFO = {"mobile-cathedral-basilica-of-the-immaculate-conception":{"yr":1962,"f":["Seat of the Archdiocese of Mobile; its parish dates to 1703, among the oldest in the United States.","Greek Revival building begun in 1835; its portico and twin towers were completed later in the 19th century.","Houses hand-painted German stained-glass windows and was designated a minor basilica in 1962."],"wu":"https://en.wikipedia.org/wiki/Cathedral_Basilica_of_the_Immaculate_Conception_(Mobile,_Alabama)"},"phoenix-st-mary-s-basilica":{"yr":1985,"f":["The oldest Catholic parish in Phoenix, founded in 1881; the current church was completed in 1914.","Franciscan-run, it holds the largest collection of stained glass in Arizona.","Pope John Paul II visited in 1987, two years after its 1985 designation as a minor basilica."],"wu":"https://en.wikipedia.org/wiki/St._Mary's_Basilica_(Phoenix)"},"san-francisco-basilica-of-st-francis-of-assisi-mission-dolores":{"yr":1952,"f":["Adjacent to Mission Dolores (1776), the oldest surviving structure in San Francisco.","The parish is the oldest in the city; the basilica church was built after the mission era.","Designated a minor basilica in 1952, among the first in the western United States."],"wu":"https://en.wikipedia.org/wiki/Mission_San_Francisco_de_As%C3%ADs"},"carmel-by-the-sea-basilica-of-mission-san-carlos-borromeo-carmel-mission":{"yr":1960,"f":["Founded in 1770 by St. Junípero Serra, who is buried at the mission and served as his headquarters.","The stone church, completed in 1797, is a landmark of Spanish colonial California architecture.","Designated a minor basilica in 1960; Serra was canonized in 2015."],"wu":"https://en.wikipedia.org/wiki/Mission_San_Carlos_Borromeo_de_Carmelo"},"alameda-st-joseph-basilica":{"yr":1972,"f":["Designed by architect H. A. Minton in the Spanish Colonial Revival style, of reinforced concrete under a red tile roof.","The present church replaced one destroyed by fire in 1919 and was consecrated in 1935.","Designated a minor basilica in 1972."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_St._Joseph,_Alameda"},"san-diego-mission-basilica-san-diego-de-alcala":{"yr":1975,"f":["The first of the 21 California missions, founded by St. Junípero Serra in 1769.","Site of California's first Christian burial ground and often called the 'Mother of the Missions.'","Designated a minor basilica in 1975."],"wu":"https://en.wikipedia.org/wiki/Mission_San_Diego_de_Alcal%C3%A1"},"san-jose-cathedral-basilica-of-st-joseph":{"yr":1995,"f":["Seat of the Diocese of San José; the parish dates to 1803, the first non-mission parish in California.","The present domed, Italian Renaissance-style church was completed in 1877 after fires and earthquakes destroyed earlier ones.","Named a minor basilica by papal decree of December 1995; the title was formally conferred in 1997."],"wu":"https://en.wikipedia.org/wiki/Cathedral_Basilica_of_St._Joseph_(San_Jose)"},"san-juan-capistrano-mission-basilica-san-juan-capistrano":{"yr":2000,"f":["The mission was founded in 1776; its Great Stone Church was ruined by an 1812 earthquake.","The present basilica church, dedicated in 1987, was modeled on the mission's lost Great Stone Church.","Famed for the annual return of the swallows; designated a minor basilica in 2000."],"wu":null},"ventura-mission-basilica-san-buenaventura":{"yr":2020,"f":["The ninth and last mission founded personally by St. Junípero Serra, in 1782.","Its adobe church, completed in 1809, sits at the heart of downtown Ventura.","Elevated to a minor basilica in 2020."],"wu":"https://en.wikipedia.org/wiki/Mission_San_Buenaventura"},"denver-cathedral-basilica-of-the-immaculate-conception":{"yr":1979,"f":["Seat of the Archdiocese of Denver; a French Gothic Revival landmark completed in 1911.","Its twin 210-foot spires and 75+ stained-glass windows are civic landmarks of Denver.","Pope John Paul II prayed here during World Youth Day 1993; designated a basilica in 1979."],"wu":"https://en.wikipedia.org/wiki/Cathedral_Basilica_of_the_Immaculate_Conception_(Denver)"},"waterbury-basilica-of-the-immaculate-conception":{"yr":2008,"f":["Renaissance Revival church completed in 1928 for Waterbury's Catholic community.","Noted for its marble interior, murals, and large pipe organ.","Designated a minor basilica in 2008."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_the_Immaculate_Conception_(Waterbury,_Connecticut)"},"stamford-basilica-of-st-john-the-evangelist":{"yr":2009,"f":["The parish began in 1847; the present church, the largest stone church in southern Connecticut, was built in 1875.","Irish Catholic parishioners dug the foundation themselves and dragged the stone from a local quarry.","Designated a minor basilica in 2009."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_Saint_John_the_Evangelist"},"washington-basilica-of-the-national-shrine-of-the-immaculate-conception":{"yr":1990,"f":["The largest Roman Catholic church in North America and the U.S. patronal shrine of the Immaculate Conception.","Byzantine-Romanesque; built 1920–1959, its Great Dome and campanile dominate the skyline near Catholic University.","Designated a minor basilica in 1990; it contains dozens of chapels honoring Marian devotions worldwide."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_the_National_Shrine_of_the_Immaculate_Conception"},"st-augustine-cathedral-basilica-of-st-augustine":{"yr":1976,"f":["Seat of the Diocese of St. Augustine; its parish (1565) is the oldest Catholic congregation in the United States.","The Spanish Colonial church was built in the 1790s and restored after an 1887 fire.","Designated a minor basilica in 1976."],"wu":"https://en.wikipedia.org/wiki/Cathedral_Basilica_of_St._Augustine"},"daytona-beach-basilica-of-st-paul":{"yr":2006,"f":["A Spanish mission-style church by architect Gerald A. Barry; its first Mass was celebrated in 1927.","A longtime landmark of downtown Daytona Beach.","Designated a minor basilica in 2006."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_St._Paul_(Daytona_Beach,_Florida)"},"orlando-basilica-of-the-national-shrine-of-mary-queen-of-the-universe":{"yr":2009,"f":["Built to serve the millions of Catholic visitors to the Orlando/theme-park region.","One of very few basilicas conceived primarily as a shrine for tourists and pilgrims.","Designated a minor basilica in 2009."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_Mary,_Queen_of_the_Universe"},"pensacola-basilica-of-st-michael-the-archangel":{"yr":2011,"f":["Traces to a Spanish colonial parish; Pensacola is among the oldest European settlements in the U.S.","The Gothic Revival church was completed in the late 19th century.","Designated a minor basilica in 2011."],"wu":null},"key-west-basilica-of-st-mary-star-of-the-sea":{"yr":2012,"f":["Founded in 1852; long the spiritual anchor of Catholic Key West.","Its grotto to Our Lady of Lourdes (1922) is said locally to protect the island from hurricanes.","Designated a minor basilica in 2012."],"wu":null},"jacksonville-basilica-of-the-immaculate-conception":{"yr":2013,"f":["One of Jacksonville's oldest congregations, rebuilt after the Great Fire of 1901.","The present church was dedicated in 1910, after the 1901 Great Fire destroyed its predecessor.","Designated a minor basilica in 2013."],"wu":null},"palm-beach-basilica-of-st-edward":{"yr":2024,"f":["Spanish Renaissance-style church completed in 1927 in the resort town of Palm Beach.","President John F. Kennedy attended Mass here during stays at the Kennedy family home.","Designated a minor basilica in 2024."],"wu":null},"atlanta-basilica-of-the-sacred-heart-of-jesus":{"yr":2010,"f":["One of Atlanta's oldest churches (1897–1898), built in Romanesque Revival style by Marist priests.","Twin spires make it a landmark of downtown Atlanta.","Designated a minor basilica in 2010."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_the_Sacred_Heart_of_Jesus_(Atlanta)"},"savannah-cathedral-basilica-of-st-john-the-baptist":{"yr":2020,"f":["Seat of the Diocese of Savannah; French Gothic, dedicated in 1876, gutted by fire in 1898 and rebuilt by 1900.","Its twin spires and painted interior make it one of the South's most photographed churches.","Designated a minor basilica in January 2020."],"wu":"https://en.wikipedia.org/wiki/Cathedral_Basilica_of_St._John_the_Baptist_(Savannah,_Georgia)"},"honolulu-cathedral-basilica-of-our-lady-of-peace":{"yr":2014,"f":["Seat of the Diocese of Honolulu and one of the oldest cathedrals in continuous use in the U.S. (dedicated 1843).","St. Damien of Molokai was ordained a priest here in 1864.","Designated a minor basilica in 2014."],"wu":"https://en.wikipedia.org/wiki/Cathedral_Basilica_of_Our_Lady_of_Peace"},"chicago-our-lady-of-sorrows-basilica":{"yr":1956,"f":["Served by the Servite Order; a center of the Friday Sorrowful Mother Novena that spread nationwide in the 1930s–40s.","Grand Renaissance/Baroque interior completed in the early 20th century.","Designated a minor basilica in 1956, the first in Chicago."],"wu":"https://en.wikipedia.org/wiki/Our_Lady_of_Sorrows_Basilica"},"chicago-queen-of-all-saints-basilica":{"yr":1962,"f":["A Gothic Revival 'jewel box' completed in 1960 on Chicago's North Side.","Designed with elaborate stone tracery, statuary, and stained glass.","Designated a minor basilica in 1962, soon after its completion."],"wu":"https://en.wikipedia.org/wiki/Queen_of_All_Saints_Basilica"},"chicago-basilica-of-st-hyacinth":{"yr":2003,"f":["A landmark of Chicago's Polish community, completed in 1921 in the Polish Cathedral style.","Its three towers and vast interior seat one of the largest congregations in the city.","Designated a minor basilica in 2003."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_Saint_Hyacinth"},"vincennes-basilica-of-st-francis-xavier-old-cathedral":{"yr":1970,"f":["Indiana's oldest parish, founded by Jesuit missionaries in 1734.","The 1826 brick church was the first cathedral of the Diocese of Vincennes.","Designated a minor basilica in 1970; its Old Cathedral Library holds rare early books."],"wu":"https://en.wikipedia.org/wiki/St._Francis_Xavier_Cathedral_and_Library"},"notre-dame-basilica-of-the-sacred-heart":{"yr":1991,"f":["The church of the University of Notre Dame, completed in 1888 by the Congregation of Holy Cross.","Home to a renowned collection of murals and the oldest carillon in North America.","Designated a minor basilica in 1991."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_the_Sacred_Heart_(Notre_Dame)"},"dyersville-basilica-of-st-francis-xavier":{"yr":1956,"f":["A soaring Gothic Revival church built 1887–1889 by German Catholic settlers on the Iowa prairie.","Its twin 212-foot spires are visible for miles; often called 'the Cathedral of the Prairie.'","Designated a minor basilica in 1956, one of the first outside a major city."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_St._Francis_Xavier,_Dyersville"},"des-moines-basilica-of-st-john-the-apostle":{"yr":1989,"f":["Romanesque church completed in 1927, a landmark of Des Moines.","Noted for its mosaics, marble, and a large central dome.","Designated a minor basilica in 1989."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_St._John_(Des_Moines,_Iowa)"},"victoria-basilica-of-st-fidelis-cathedral-of-the-plains":{"yr":2014,"f":["Built 1908–1911 by Volga-German immigrants; nicknamed the 'Cathedral of the Plains' by William Jennings Bryan.","Its twin 141-foot towers make it one of the largest churches in the Great Plains.","Constructed largely with hand-hauled native limestone by the parishioners themselves."],"wu":null},"trappist-basilica-of-the-blessed-virgin-of-gethsemani":{"yr":1949,"f":["Church of the Abbey of Gethsemani (1848), the oldest Trappist monastery in the U.S.","Home of the writer-monk Thomas Merton, who lived and is buried here.","Designated a minor basilica in 1949."],"wu":"https://en.wikipedia.org/wiki/Abbey_of_Our_Lady_of_Gethsemani"},"covington-cathedral-basilica-of-the-assumption":{"yr":1953,"f":["Seat of the Diocese of Covington; a French Gothic design modeled partly on Notre-Dame de Paris.","Contains one of the world's largest handmade stained-glass windows.","Designated a minor basilica in 1953."],"wu":"https://en.wikipedia.org/wiki/Cathedral_Basilica_of_the_Assumption_(Covington,_Kentucky)"},"bardstown-st-joseph-proto-cathedral-basilica":{"yr":2001,"f":["The first Catholic cathedral built west of the Appalachians (1816–1819).","Its art collection includes paintings gifted by European royalty and popes.","'Proto-cathedral' marks it as the mother church of the interior U.S.; designated a basilica in 2001."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_St._Joseph_Proto-Cathedral"},"new-orleans-cathedral-basilica-of-st-louis-king-of-france":{"yr":1964,"f":["The oldest continuously active Catholic cathedral in the United States; present church dedicated 1794.","Its triple-spired facade on Jackson Square is an icon of New Orleans.","Designated a minor basilica in 1964; Pope John Paul II visited in 1987."],"wu":"https://en.wikipedia.org/wiki/St._Louis_Cathedral_(New_Orleans)"},"natchitoches-basilica-of-the-immaculate-conception":{"yr":2009,"f":["Serves the oldest permanent settlement in the Louisiana Purchase (Natchitoches, founded 1714).","The present Romanesque church dates to the 1850s.","Designated a minor basilica in 2009."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_the_Immaculate_Conception_(Natchitoches,_Louisiana)"},"new-orleans-basilica-of-st-stephen":{"yr":2022,"f":["A towering Gothic Revival church completed in 1887 by the Vincentians.","Its steeple is among the tallest in New Orleans.","Designated a minor basilica in 2022."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_St._Stephen_(New_Orleans)"},"lewiston-basilica-of-sts-peter-and-paul":{"yr":2004,"f":["A vast Gothic church built by French-Canadian mill workers, completed in 1935 and dedicated in 1938.","One of the largest churches in New England, seating around 2,000.","Designated a minor basilica in 2004."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_Saints_Peter_and_Paul_(Lewiston,_Maine)"},"baltimore-basilica-of-the-national-shrine-of-the-assumption-of-the-bvm":{"yr":1937,"f":["The first Roman Catholic cathedral in the United States, built 1806–1821.","Designed by Benjamin Henry Latrobe, architect of the U.S. Capitol, in Neoclassical style.","Seat of the first U.S. diocese (Baltimore); designated a minor basilica in 1937."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_the_National_Shrine_of_the_Assumption_of_the_Blessed_Virgin_Mary"},"emmitsburg-basilica-of-the-national-shrine-of-st-elizabeth-ann-seton":{"yr":1991,"f":["Enshrines the remains of St. Elizabeth Ann Seton, the first native-born U.S. citizen canonized a saint.","Adjoins the site where she founded the Sisters of Charity and American parochial schooling.","Designated a minor basilica in 1991."],"wu":"https://en.wikipedia.org/wiki/National_Shrine_of_St._Elizabeth_Ann_Seton"},"boston-basilica-shrine-of-our-lady-of-perpetual-help-mission-church":{"yr":1954,"f":["Run by the Redemptorists; a Romanesque landmark in Roxbury completed in 1878, its towers added 1910.","Famous as a shrine of healing, with walls once lined with crutches left by pilgrims.","Designated a minor basilica in 1954."],"wu":"https://en.wikipedia.org/wiki/Basilica_and_Shrine_of_Our_Lady_of_Perpetual_Help"},"chicopee-basilica-of-st-stanislaus":{"yr":1991,"f":["A brownstone church in the Baroque Revival style, seating at least 800 in its main nave and two side naves.","Parish founded in 1891; its church was built in 1908.","Designated a minor basilica in 1991."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_St._Stanislaus_(Chicopee,_Massachusetts)"},"webster-st-joseph-basilica":{"yr":1998,"f":["The parish was established in 1887 as the first Polish-American church in New England.","Corinthian columns support a 2,000-pound main altar of green Florentine marble; the walls hold 55 life-size murals.","Designated a minor basilica in 1998."],"wu":"https://en.wikipedia.org/wiki/St._Joseph_Basilica_(Webster,_Massachusetts)"},"grand-rapids-basilica-of-st-adalbert":{"yr":1979,"f":["The mother church of Grand Rapids' Polish community, completed 1913 in Renaissance style.","Its dome and twin towers are West Michigan landmarks.","Designated a minor basilica in 1979."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_St._Adalbert_(Grand_Rapids,_Michigan)"},"royal-oak-national-shrine-of-the-little-flower-basilica":{"yr":2014,"f":["Built by the controversial radio priest Fr. Charles Coughlin in the 1930s.","Its Art Deco 'Charity Crucifixion Tower' is a striking modern landmark.","Dedicated to St. Thérèse of Lisieux; designated a minor basilica by decree of December 2014 (announced 2015)."],"wu":"https://en.wikipedia.org/wiki/National_Shrine_of_the_Little_Flower_Basilica"},"detroit-basilica-of-ste-anne-de-detroit":{"yr":2020,"f":["The second-oldest continuously operating Catholic parish in the U.S., founded in 1701 with the city of Detroit.","The current Gothic Revival church (1886) preserves relics of Fr. Gabriel Richard.","Designated a minor basilica in 2020."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_Sainte_Anne_de_D%C3%A9troit"},"minneapolis-basilica-of-st-mary":{"yr":1926,"f":["The first church in the United States designated a minor basilica (January 1926).","Beaux-Arts building constructed 1907–1914; co-cathedral of the Archdiocese of St. Paul and Minneapolis.","Hosts a well-known summer music and arts festival."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_Saint_Mary_(Minneapolis)"},"winona-basilica-of-st-stanislaus-kostka":{"yr":2011,"f":["A monumental Polish Cathedral-style church completed in 1895 above the Mississippi River.","Its great copper dome is a landmark of Winona.","Serves one of Minnesota's historic Polish parishes."],"wu":null},"natchez-st-mary-basilica":{"yr":1998,"f":["The former cathedral of the Diocese of Natchez, built beginning 1842.","A Gothic Revival landmark on the Mississippi River bluff.","Served as the cathedral of the Diocese of Natchez from 1843 to 1977."],"wu":"https://en.wikipedia.org/wiki/St._Mary_Basilica,_Natchez"},"conception-basilica-of-the-immaculate-conception-conception-abbey":{"yr":1940,"f":["Church of a Benedictine monastery founded by Swiss monks in 1873.","Romanesque church noted for murals painted by monks of the Beuron art school.","Designated in 1940, the fifth minor basilica in the United States."],"wu":"https://en.wikipedia.org/wiki/Conception_Abbey"},"st-louis-basilica-of-st-louis-king-of-france-old-cathedral":{"yr":1961,"f":["The oldest cathedral west of the Mississippi; the present church was dedicated in 1834.","Stands beside the Gateway Arch on the church block set aside at the city's founding in 1764.","Designated a minor basilica in 1961."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_St._Louis,_King_of_France"},"st-louis-cathedral-basilica-of-st-louis-new-cathedral":{"yr":1997,"f":["Seat of the Archdiocese of St. Louis; a Byzantine-Romanesque church begun in 1907 and consecrated in 1926.","Its mosaics cover 83,000 square feet, about 41.5 million tesserae.","Designated a minor basilica in 1997; Pope John Paul II visited in 1999."],"wu":"https://en.wikipedia.org/wiki/Cathedral_Basilica_of_Saint_Louis_(St._Louis)"},"newark-cathedral-basilica-of-the-sacred-heart":{"yr":1995,"f":["Seat of the Archdiocese of Newark; a French Gothic cathedral built 1899–1954.","One of the largest cathedrals in North America, with 232-foot twin towers.","Pope John Paul II led a prayer service here in 1995; designated a basilica in 1995."],"wu":"https://en.wikipedia.org/wiki/Cathedral_Basilica_of_the_Sacred_Heart_(Newark)"},"santa-fe-cathedral-basilica-of-st-francis-of-assisi":{"yr":2005,"f":["Built by Archbishop Jean-Baptiste Lamy (the model for Willa Cather's novel) beginning 1869.","Romanesque Revival in style, unusual among New Mexico's adobe churches.","Houses 'La Conquistadora,' the oldest Marian statue venerated in the United States."],"wu":"https://en.wikipedia.org/wiki/Cathedral_Basilica_of_St._Francis_of_Assisi_(Santa_Fe)"},"mesilla-basilica-of-san-albino":{"yr":2008,"f":["Anchors the historic plaza of Mesilla, near Las Cruces, a key site on the old Camino Real.","The present brick church dates to 1906, replacing an 1850s adobe chapel.","Founded as a mission in 1852; the present church was dedicated in 1908."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_San_Albino"},"lackawanna-basilica-of-our-lady-of-victory-national-shrine":{"yr":1926,"f":["Built 1921–1926 by Venerable Nelson Baker as the heart of his 'City of Charity.'","White Georgia marble with a great copper dome; one of the first two U.S. basilicas (1926).","Fr. Baker, declared Venerable in 2011, is entombed within."],"wu":"https://en.wikipedia.org/wiki/Our_Lady_of_Victory_Basilica_(Lackawanna,_New_York)"},"brooklyn-basilica-of-our-lady-of-perpetual-help":{"yr":1969,"f":["A Redemptorist parish founded in 1892; its granite double church opened in 1909 (lower) and 1928 (upper).","The upper church's Golden Shrine holds the painted icon of Our Lady of Perpetual Help.","Designated a minor basilica in 1969."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_Our_Lady_of_Perpetual_Help_(Brooklyn)"},"lewiston-basilica-of-the-national-shrine-of-our-lady-of-fatima":{"yr":1975,"f":["Run by the Barnabite Fathers; centered on a large glass-domed 'Basilica' near Niagara Falls.","A 13-foot granite Our Lady of Fatima statue stands atop a domed globe over the shrine.","Surrounded by outdoor gardens with saints' statues from around the world."],"wu":null},"brooklyn-cathedral-basilica-of-st-james":{"yr":1982,"f":["The oldest Catholic parish on Long Island, tracing to 1822.","The cathedral of the Diocese of Brooklyn since 1853; today's Neo-Georgian church dates to 1903.","Designated a minor basilica in 1982."],"wu":"https://en.wikipedia.org/wiki/Cathedral_Basilica_of_St._James_(Brooklyn)"},"syracuse-basilica-of-the-sacred-heart-of-jesus":{"yr":1998,"f":["Parish founded in 1892; the present church was dedicated in 1910.","A Gothic church in the form of a cross, built of steel-framed stone faced with Gouverneur marble, with twin 212-foot spires.","Designated a minor basilica in 1998."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_the_Sacred_Heart_of_Jesus,_Syracuse"},"new-york-basilica-of-st-patrick-s-old-cathedral":{"yr":2010,"f":["New York City's original Catholic cathedral, dedicated in 1815 before the current St. Patrick's on Fifth Avenue.","Two walled cemeteries and catacombs surround the church; the wall went up in 1834 against anti-Catholic mobs.","Designated a minor basilica in 2010."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_St._Patrick's_Old_Cathedral"},"southampton-basilica-of-the-sacred-hearts-of-jesus-and-mary":{"yr":2011,"f":["A Gothic-style church built in 1908 of white marble blocks.","Its handmade stained glass windows came from Austria, and its 400-year-old wooden pulpit was imported from France.","Designated a minor basilica in 2011."],"wu":null},"brooklyn-basilica-of-regina-pacis":{"yr":2012,"f":["Built to fulfill a 1942 wartime vow to Mary, Queen of Peace, and dedicated in 1951.","Parishioners gave their own jewelry for its crowns; stolen in 1952, they came back eight days later.","Designated a minor basilica in 2012."],"wu":"https://en.wikipedia.org/wiki/Regina_Pacis_Votive_Shrine"},"olean-basilica-of-st-mary-of-the-angels":{"yr":2017,"f":["Begun as a mission in 1852 and made a parish in 1876; the present church opened in 1915.","Designed by architect Emile M. Ulrich and built almost entirely of white Pennsylvania marble, with twin 150-foot towers.","Designated a minor basilica in 2017."],"wu":null},"asheville-basilica-of-st-lawrence":{"yr":1993,"f":["Designed by Rafael Guastavino, the master builder who is entombed in the church.","Features a self-supporting tiled elliptical dome, one of the largest freestanding domes in North America.","Completed in 1909; designated a minor basilica in 1993."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_St._Lawrence,_Asheville"},"belmont-basilica-of-our-lady-help-of-christians-belmont-abbey":{"yr":1998,"f":["Church of a Benedictine abbey and college founded in 1876.","Was once the only 'abbey nullius' (abbey-diocese) in the United States.","Its abbey church was designated a minor basilica in 1998."],"wu":"https://en.wikipedia.org/wiki/Belmont_Abbey,_North_Carolina"},"wilmington-basilica-shrine-of-st-mary":{"yr":2013,"f":["Designed by Rafael Guastavino, famous for structural tile vaulting; completed 1911.","Its Spanish Baroque facade and tiled interior are architectural landmarks of Wilmington.","One of two Guastavino basilicas in North Carolina."],"wu":null},"jamestown-basilica-of-st-james":{"yr":1988,"f":["A Romanesque Revival 'basilica on the prairie' completed in the early 20th century.","Briefly the cathedral of the Diocese of Jamestown (1889–1891); the church was consecrated in 1914.","The state's only minor basilica."],"wu":null},"carey-basilica-national-shrine-of-our-lady-of-consolation":{"yr":1971,"f":["A major Marian pilgrimage shrine centered on a statue of Our Lady of Consolation brought from Luxembourg in 1875.","Draws tens of thousands of pilgrims each year, especially on the August feast.","Run by the Conventual Franciscans; a national shrine and minor basilica."],"wu":"https://en.wikipedia.org/wiki/Basilica_and_National_Shrine_of_Our_Lady_of_Consolation"},"canton-basilica-of-st-john-the-baptist":{"yr":2012,"f":["Parish founded in 1823; the present church was dedicated in 1872.","A new church was needed by 1867 for the growing parish; its cornerstone was laid on July 10, 1870.","Designated a minor basilica in 2012."],"wu":null},"marietta-basilica-of-st-mary-of-the-assumption":{"yr":2013,"f":["Serves Marietta, the first permanent U.S. settlement in the Northwest Territory (1788).","The present church was built 1903–1905 and dedicated in 1909.","Designated a minor basilica in 2013."],"wu":null},"youngstown-basilica-of-our-lady-of-mount-carmel":{"yr":2014,"f":["Begun as a mission church in 1908 and a parish by 1913; the church was dedicated on November 4, 1916.","A fire on June 12, 1923, destroyed its pipe organ and damaged the church, which was rededicated that December 16.","Designated a minor basilica in 2014."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_Our_Lady_of_Mount_Carmel_(Youngstown,_Ohio)"},"north-jackson-basilica-national-shrine-of-our-lady-of-lebanon":{"yr":2014,"f":["A Maronite Catholic national shrine set on a hilltop in northeastern Ohio.","Features a large statue of Our Lady of Lebanon overlooking pilgrimage grounds.","The shrine was dedicated on Aug. 15, 1965, and designated a minor basilica in 2014."],"wu":"https://en.wikipedia.org/wiki/Basilica_and_National_Shrine_of_Our_Lady_of_Lebanon_(North_Jackson,_Ohio)"},"cincinnati-cathedral-basilica-of-st-peter-in-chains":{"yr":2020,"f":["Seat of the Archdiocese of Cincinnati; a Greek Revival landmark dedicated in 1845.","Its spire soars 220 feet above street level.","Designated a minor basilica in 2020, the first in the Archdiocese of Cincinnati."],"wu":"https://en.wikipedia.org/wiki/Cathedral_Basilica_of_St._Peter_in_Chains"},"lancaster-basilica-of-st-mary-of-the-assumption":{"yr":2022,"f":["Parish founded in 1817; the present church was consecrated in 1864.","A square-towered Gothic Revival church, it was a cathedral candidate when the Diocese of Columbus was created in 1868.","Designated a minor basilica in 2022."],"wu":null},"latrobe-st-vincent-archabbey-basilica":{"yr":1955,"f":["Church of Saint Vincent Archabbey, the first Benedictine monastery in the U.S. (founded 1846 by Boniface Wimmer).","Home to Saint Vincent College and Seminary; an archabbey, the highest Benedictine rank.","The present church was consecrated in 1905 and designated a minor basilica in 1955."],"wu":"https://en.wikipedia.org/wiki/Saint_Vincent_Archabbey"},"hanover-basilica-of-the-sacred-heart-of-jesus-conewago-chapel":{"yr":1962,"f":["Conewago Chapel is the oldest stone Catholic church in the U.S. dedicated to the Sacred Heart (1787).","Founded by Jesuit missionaries; long a mother church of Catholicism in rural Pennsylvania.","Designated a minor basilica in 1962."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_the_Sacred_Heart_of_Jesus,_Conewago"},"philadelphia-cathedral-basilica-of-sts-peter-and-paul":{"yr":1976,"f":["Seat of the Archdiocese of Philadelphia; an Italian Renaissance cathedral built 1846–1864.","Its brownstone dome and copper lantern dominate the Benjamin Franklin Parkway.","Site of papal visits by John Paul II (1979) and Francis (2015)."],"wu":"https://en.wikipedia.org/wiki/Cathedral_Basilica_of_Saints_Peter_and_Paul_(Philadelphia)"},"danville-basilica-of-sts-cyril-and-methodius":{"yr":1989,"f":["Motherhouse church of the Sisters of Saints Cyril and Methodius, a Slovak religious congregation.","Dedicated in 1939 amid the Great Depression, it was built to double as the chapel for the sisters' school.","Designated a minor basilica in 1989."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_Saints_Cyril_and_Methodius_(Danville,_Pennsylvania)"},"scranton-basilica-of-the-national-shrine-of-st-ann":{"yr":1996,"f":["Home of the St. Ann's Solemn Novena, which draws hundreds of thousands of pilgrims each July.","Run by the Passionist order in Scranton's coal-country heartland.","One of the largest annual devotional gatherings in the northeastern U.S."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_the_National_Shrine_of_St._Ann"},"loretto-basilica-of-st-michael-the-archangel":{"yr":1996,"f":["Stands where Prince Demetrius Gallitzin, the 'Apostle of the Alleghenies,' founded a frontier mission in 1799.","Built with support from industrialist Charles M. Schwab in the early 20th century.","Gallitzin's grave and shrine are on the grounds."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_St._Michael_the_Archangel_(Loretto,_Pennsylvania)"},"philadelphia-basilica-shrine-of-our-lady-of-the-miraculous-medal":{"yr":2022,"f":["Home of the Central Association of the Miraculous Medal, run by the Vincentians.","Its Monday Miraculous Medal Novena became one of the most widespread U.S. devotions.","Designated a minor basilica in 2022."],"wu":"https://en.wikipedia.org/wiki/Basilica_Shrine_of_Our_Lady_of_the_Miraculous_Medal"},"columbia-basilica-of-st-peter":{"yr":2018,"f":["Parish founded in 1821; the present church was built 1906–1909.","Designed by Frank Pierce Milburn in dark red brick with Bedford stone trim; its spire's cross stands 163 feet high.","Designated a minor basilica in 2018."],"wu":null},"chattanooga-basilica-of-sts-peter-and-paul":{"yr":2011,"f":["Parish founded in 1852; the present Gothic Revival church was built 1888–1890.","Its tall spire is a downtown landmark.","Designated a minor basilica in 2011, Tennessee's only one."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_Sts._Peter_and_Paul_(Chattanooga)"},"galveston-st-mary-cathedral-basilica":{"yr":1979,"f":["The first cathedral in Texas; its brick church opened in 1848.","Survived the catastrophic 1900 Galveston Hurricane; topped by a 'Mary, Star of the Sea' statue.","Designated a minor basilica in 1979."],"wu":"https://en.wikipedia.org/wiki/St._Mary_Cathedral_Basilica_(Galveston,_Texas)"},"san-antonio-basilica-of-the-national-shrine-of-the-little-flower":{"yr":1998,"f":["Beaux-Arts, designed by Charles L. Monnot and built 1926–1931, with Mediterranean and Spanish motifs.","Discalced Carmelite friars from Torreón, Mexico, built it as a national shrine to St. Thérèse.","Raised to a minor basilica and listed on the National Register of Historic Places in 1998."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_the_National_Shrine_of_the_Little_Flower"},"san-juan-basilica-of-the-national-shrine-of-our-lady-of-san-juan-del-valle":{"yr":1999,"f":["A major Marian pilgrimage site in the Rio Grande Valley, drawing over a million visitors a year.","In 1970 a small plane crashed into the original shrine; the statue and Blessed Sacrament were saved.","The present basilica was dedicated in 1980 and designated a minor basilica in 1999."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_the_National_Shrine_of_Our_Lady_of_San_Juan_del_Valle"},"beaumont-st-anthony-cathedral-basilica":{"yr":2006,"f":["The present church dates to 1907; it became a cathedral when the Diocese of Beaumont was created in 1966.","An Italian Renaissance Revival church with a copper dome and a marble altar; a Recorded Texas Historic Landmark.","Designated a minor basilica in 2006."],"wu":"https://en.wikipedia.org/wiki/Saint_Anthony_Cathedral_Basilica"},"norfolk-basilica-of-st-mary-of-the-immaculate-conception":{"yr":1991,"f":["One of the oldest Catholic churches in Virginia and a historic African-American Catholic parish.","The Gothic Revival church was completed in 1858 and survived Civil War-era Norfolk.","Designated a minor basilica in 1991."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_Saint_Mary_of_the_Immaculate_Conception_(Norfolk,_Virginia)"},"alexandria-basilica-of-st-mary":{"yr":2017,"f":["The oldest Catholic parish in Virginia, founded in 1795.","George Washington is traditionally said to have contributed to the parish's founding fund.","Designated the 84th U.S. minor basilica (announced 2018)."],"wu":null},"roanoke-basilica-of-st-andrew":{"yr":2023,"f":["A twin-spired High Victorian Gothic church completed in 1902, a landmark on a Roanoke hilltop.","One of the most prominent churches in southwestern Virginia.","Designated a minor basilica in September 2023, among the newest in the U.S."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_St._Andrew_(Roanoke,_Virginia)"},"charleston-basilica-of-the-co-cathedral-of-the-sacred-heart":{"yr":2009,"f":["Co-cathedral of the Diocese of Wheeling-Charleston; completed in 1897.","A Romanesque/Gothic landmark in West Virginia's capital.","West Virginia's only minor basilica."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_the_Co-Cathedral_of_the_Sacred_Heart"},"milwaukee-basilica-of-st-josaphat":{"yr":1929,"f":["Built 1897–1901 by Polish immigrants, partly from salvage of a demolished Chicago federal building.","Its copper dome is modeled on St. Peter's Basilica in Rome.","The third minor basilica in the United States, designated in 1929."],"wu":"https://en.wikipedia.org/wiki/Basilica_of_St._Josaphat"},"hubertus-basilica-of-our-lady-of-holy-hill-help-of-christians":{"yr":2006,"f":["A Discalced Carmelite shrine crowning a glacial hill northwest of Milwaukee.","Its Neo-Romanesque towers and scenic overlook draw pilgrims and tourists year-round.","A national shrine and minor basilica dedicated to Mary, Help of Christians."],"wu":"https://en.wikipedia.org/wiki/Holy_Hill_National_Shrine_of_Mary,_Help_of_Christians"}};
